import { displayEthCompact } from '../app/scaling.js';
import { formatWhalePassAward } from '../app/whale-pass-format.js';
import { decimatorEntryName, decimatorWhole, decimatorTableField, decimatorFinalCutoff } from './decimator-table.js';
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const amount = value => decimatorWhole(value).toLocaleString('en-US');
const compact = value => {
  const n = BigInt(value ?? 0);
  for (const [unit, suffix] of [[10n**15n,'Q'],[10n**12n,'T'],[10n**9n,'B'],[10n**6n,'M'],[1000n,'K']]) {
    if (n >= unit) {
      const tenths = (n * 10n + unit / 2n) / unit;
      return `${tenths / 10n}${tenths % 10n ? `.${tenths % 10n}` : ''}${suffix}`;
    }
  }
  return n.toLocaleString('en-US');
};
const bind = (host, name) => host.querySelector(`[data-bind="${name}"]`);
const prize = row => [BigInt(row.ethWei ?? 0) > 0n ? `${displayEthCompact(BigInt(row.ethWei))} ETH` : '',
  BigInt(row.halfPasses ?? 0) > 0n ? formatWhalePassAward(row.halfPasses) : ''].filter(Boolean).join(' + ');

export function paintDecimatorHeader(host, skin) {
  const { snapshot } = skin;
  const logo = host.querySelector('.craps-dialog__brand-logo');
  logo.src = '/app/assets/decimator-logo.svg?v=casino-v2'; logo.alt = 'Decimator Craps Battle';
  bind(host, 'craps-dialog').setAttribute('aria-label', `Level ${snapshot.level} Decimator craps battle`);
  const marquee = bind(host, 'craps-prize-marquee'); marquee.hidden = false;
  for (const name of ['craps-jackpot-marquee','craps-biggest-marquee','craps-bounty-added']) bind(host, name).hidden = true;
  const bounty = bind(host, 'craps-bounty-marquee'); bounty.hidden = false;
  bind(host, 'craps-bounty-label').textContent = `LEVEL ${snapshot.level} · PRIZE POOL`;
  bind(host, 'craps-bounty-amount').textContent = displayEthCompact(BigInt(snapshot.poolWei ?? 0));
  bounty.querySelector('em').textContent = 'ETH';
  bounty.setAttribute('aria-label', `${displayEthCompact(BigInt(snapshot.poolWei ?? 0))} ETH and Whale Passes`);
  const goal = bind(host, 'craps-title-goal'); goal.hidden = false;
  goal.querySelector('small').textContent = `FINAL TOP ${snapshot.winnerCount}`;
  goal.querySelector('em').textContent = 'SCORE';
  const cutoff = decimatorFinalCutoff(skin);
  bind(host, 'craps-title-goal-amount').textContent = cutoff == null ? '—' : compact(cutoff);
  goal.setAttribute('aria-label', `Final paid cutoff ${cutoff?.toLocaleString('en-US') ?? 'unavailable'} score. Tied scores use draw order.`);
}

export function paintDecimatorStatus(host, skin, round, standings, liveStack = null) {
  const local = standings.find(row => row.local);
  bind(host, 'craps-race-rank').textContent = local?.rank ? `#${local.rank}` : 'OUT';
  bind(host, 'craps-race-left').textContent = String(standings.filter(row => row.state === 'live').length);
  bind(host, 'craps-race-total').textContent = String(skin.snapshot.fieldEntries ?? skin.snapshot.entrants);
  bind(host, 'craps-race-stack').textContent = compact(local?.amount);
  bind(host, 'craps-race-stack').title = (local?.amount ?? 0n).toLocaleString('en-US');
  bind(host, 'craps-race-stack-target').querySelector('small').textContent = 'PEAK SCORE';
  const note = bind(host, 'craps-decimator-note');
  if (note) {
    const start = decimatorWhole(skin.selected.stack);
    const live = liveStack ?? local?.liveStack ?? start;
    const flipLost = skin.finalFlipRevealed && !skin.selected.eligible;
    note.textContent = `#${skin.selected.entryId} ${skin.selected.generated ? 'JACKPOT' : 'BURN'} · START ${compact(start)} · ${flipLost ? 'FINAL FLIP: TAILS · OUT' : `STACK ${compact(live)} · Peak score stays after bust.`}`;
    note.title = `${amount(skin.selected.stack)} credited starting stack. Peak score = starting stack × best completed-shooter multiple. The gold line marks the final paid cutoff.`;
  }
  paintDecimatorHeader(host, skin);
}

export function wireDecimatorField(host, skin) {
  const toggle = bind(host, 'craps-decimator-field-toggle');
  const panel = bind(host, 'craps-decimator-field');
  let offset = 0;
  const draw = () => {
    const page = decimatorTableField(skin, offset);
    panel.innerHTML = `<header><strong>FULL FIELD · ${page.total} ENTRIES</strong><button type="button" data-field-close>CLOSE FIELD</button></header>
      <p>Every burn and jackpot entry. Final flips are revealed at the end.</p>
      <ol>${page.rows.map(row => `<li data-entry-id="${esc(row.entryId)}"${skin.finalFlipRevealed ? ` data-eligible="${row.eligible}"` : ''}><span>#${esc(row.entryId)} · ${esc(decimatorEntryName(row, skin.names))}</span><span>${row.generated ? 'JACKPOT' : 'BURN'} · ${amount(row.stack)}</span><strong>${skin.finalFlipRevealed ? row.eligible ? 'HEADS' : 'TAILS' : '—'}</strong></li>`).join('')}</ol>
      <footer><button type="button" data-field-prev ${offset === 0 ? 'disabled' : ''}>PREV</button><span>${offset + 1}–${offset + page.rows.length} / ${page.total}</span><button type="button" data-field-next ${offset + page.rows.length >= page.total ? 'disabled' : ''}>NEXT</button></footer>`;
    panel.querySelector('[data-field-close]').onclick = () => { panel.hidden = true; toggle.setAttribute('aria-expanded', 'false'); toggle.focus(); };
    panel.querySelector('[data-field-prev]').onclick = () => { offset = Math.max(0,offset - 25); draw(); };
    panel.querySelector('[data-field-next]').onclick = () => { offset += 25; draw(); };
  };
  toggle.textContent = `FULL FIELD · ${skin.snapshot.fieldEntries ?? skin.snapshot.entrants}`;
  toggle.onclick = () => { panel.hidden = !panel.hidden; toggle.setAttribute('aria-expanded', String(!panel.hidden)); if (!panel.hidden) { draw(); panel.querySelector('button').focus(); } };
  panel.hidden = true;
}

const coinFace = heads => `/shared/coinflip-face-${heads ? 'eth' : 'red'}.svg`;
function showResult(host, label) {
  const splash = bind(host, 'craps-race-result');
  splash.hidden = false; splash.removeAttribute('hidden'); splash.classList.add('is-visible');
  splash.setAttribute('aria-label', label);
  return bind(host, 'craps-race-result-card');
}

export function paintDecimatorFinalFlip(host, skin) {
  const card = showResult(host, 'Decimator final flip');
  card.innerHTML = `<div class="craps-decimator-eyebrow">DECIMATOR · LEVEL ${skin.snapshot.level}</div>
    <h2>FINAL FLIP</h2>
    <div class="craps-decimator-flip" aria-hidden="true"><div class="craps-decimator-flip__coin${skin.selected.eligible ? '' : ' is-tails'}">
      <img src="${coinFace(true)}" alt=""><img src="${coinFace(false)}" alt="">
    </div></div>
    <p class="craps-decimator-result-note" role="status">Heads keeps your score in contention.</p>`;
}

export function paintDecimatorResult(host, skin, standings) {
  const { snapshot } = skin;
  const local = standings.find(row => row.local);
  const ownedWins = snapshot.winners.filter(row => row.address?.toLowerCase() === snapshot.you?.address?.toLowerCase());
  const totals = ownedWins.reduce((sum, row) => ({ ethWei: sum.ethWei + BigInt(row.ethWei ?? 0), halfPasses: sum.halfPasses + BigInt(row.halfPasses ?? 0) }), { ethWei: 0n, halfPasses: 0n });
  const heads = skin.selected.eligible;
  const title = ownedWins.length ? 'IN THE MONEY' : heads ? 'BATTLE COMPLETE' : 'TAILS · OUT';
  const card = showResult(host, `Decimator results. Final flip: ${heads ? 'heads' : 'tails'}. ${title}.`);
  const summary = () => {
    card.innerHTML = `<div class="craps-decimator-eyebrow">DECIMATOR · LEVEL ${snapshot.level} · ENTRY #${esc(skin.selected.entryId)}</div>
      <div class="craps-decimator-outcome"><img src="${coinFace(heads)}" alt=""><strong>FINAL FLIP · ${heads ? 'HEADS' : 'TAILS'}</strong></div>
      <h2>${title}</h2>
      <div class="craps-decimator-payout"><small>YOUR TOTAL PRIZE</small><strong>${ownedWins.length ? esc(prize(totals)) : 'No prize this time'}</strong></div>
      <dl class="craps-decimator-stats">
        <div><dt>PEAK SCORE</dt><dd title="${local?.amount ?? 0n}">${compact(local?.amount)}</dd></div>
        <div><dt>FINAL RANK</dt><dd>${local?.rank ? `#${local.rank}` : 'OUT'}</dd></div>
        <div><dt>PAID CUTOFF</dt><dd title="${amount(snapshot.winners.at(-1)?.score)}">${compact(decimatorWhole(snapshot.winners.at(-1)?.score))}</dd></div>
      </dl>
      <p class="craps-decimator-result-note">${heads ? 'Heads keeps your peak score. Top scores win.' : 'Tails ends this entry’s run.'}${ownedWins.length && !heads ? ' Your other entries won prizes.' : ''}</p>
      <div class="craps-decimator-result-actions"><button type="button" data-dec-winners>WINNERS · ${snapshot.winners.length}</button><button type="button" data-bind="craps-race-exit">DONE</button></div>`;
    card.querySelector('[data-dec-winners]').onclick = () => winners(0);
  };
  const winners = offset => {
    const pageSize = 3;
    const rows = snapshot.winners.slice(offset, offset + pageSize);
    card.innerHTML = `<div class="craps-decimator-eyebrow">DECIMATOR · LEVEL ${snapshot.level}</div><h2>WINNERS</h2>
      <ol class="craps-decimator-winners">${rows.map(row => `<li><b>#${row.rank} ${esc(decimatorEntryName(row, skin.names))}</b><span title="${amount(row.score)}">${compact(decimatorWhole(row.score))} SCORE</span><strong>${esc(prize(row))}</strong></li>`).join('')}</ol>
      <nav class="craps-decimator-pages" aria-label="Winner pages"><button type="button" data-dec-prev ${offset === 0 ? 'disabled' : ''}>PREV</button><span>${offset + 1}–${offset + rows.length} OF ${snapshot.winners.length}</span><button type="button" data-dec-next ${offset + pageSize >= snapshot.winners.length ? 'disabled' : ''}>NEXT</button></nav>
      <div class="craps-decimator-result-actions"><button type="button" data-dec-summary>YOUR RESULT</button><button type="button" data-bind="craps-race-exit">DONE</button></div>`;
    card.querySelector('[data-dec-prev]').onclick = () => winners(offset - pageSize);
    card.querySelector('[data-dec-next]').onclick = () => winners(offset + pageSize);
    card.querySelector('[data-dec-summary]').onclick = () => { summary(); card.querySelector('[data-dec-winners]').focus(); };
    card.querySelector('[data-dec-summary]').focus();
  };
  summary();
  bind(host, 'craps-dice-bay').setAttribute('aria-label', 'Decimator battle complete. Prizes are shown in ETH and Whale Passes.');
  card.querySelector('[data-bind="craps-race-exit"]').focus({ preventScroll: true });
}
